class Solution:
    def validSquare(self, p1, p2, p3, p4) -> bool:
        def dist(a, b):
            return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2
        dists = sorted([dist(p1, p2), dist(p1, p3), dist(p1, p4),
                        dist(p2, p3), dist(p2, p4), dist(p3, p4)])
        return (dists[0] > 0 and
                dists[0] == dists[1] == dists[2] == dists[3] and
                dists[4] == dists[5])

